<?php

namespace App\Support;

use JsonException;
use RuntimeException;

final class CatalogCounties
{
    /**
     * ISO 3166-2 subdivision snapshot for every EU country in
     * CatalogCountries::EU_CODES, plus business taxonomy supplements for
     * football-association countries that are represented separately in the
     * catalogue (for example England = ENG rather than United Kingdom = GB).
     *
     * Source snapshot for the base payload: pycountry 24.6.1 / ISO 3166-2.
     */
    private const DATA = '';

    private static ?array $decoded = null;

    public static function all(): array
    {
        if (self::$decoded !== null) {
            return self::$decoded;
        }

        $compressed = base64_decode(self::DATA, true);
        $json = $compressed === false ? false : gzuncompress($compressed);
        if (! is_string($json)) {
            throw new RuntimeException('The EU county dataset could not be decoded.');
        }

        try {
            $decoded = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
        } catch (JsonException $exception) {
            throw new RuntimeException('The EU county dataset is invalid.', previous: $exception);
        }

        if (! is_array($decoded)) {
            throw new RuntimeException('The EU county dataset is invalid.');
        }

        $decoded['ENG'] = CatalogEngland::COUNTIES;

        return self::$decoded = $decoded;
    }

    public static function forCountry(?string $countryCode): array
    {
        $countryCode = strtoupper(trim((string) $countryCode));

        return self::all()[$countryCode] ?? [];
    }

    public static function countryCodes(): array
    {
        return array_keys(self::all());
    }

    public static function codesForCountry(?string $countryCode): array
    {
        return array_column(self::forCountry($countryCode), 'code');
    }

    public static function isValid(?string $countryCode, ?string $countyCode): bool
    {
        $countyCode = strtoupper(trim((string) $countyCode));
        if ($countyCode === '') {
            return false;
        }

        foreach (self::forCountry($countryCode) as $county) {
            if (strtoupper((string) ($county['code'] ?? '')) === $countyCode) {
                return true;
            }
        }

        return false;
    }

    public static function find(?string $countryCode, ?string $countyCode): ?array
    {
        $countyCode = strtoupper(trim((string) $countyCode));
        foreach (self::forCountry($countryCode) as $county) {
            if (strtoupper((string) ($county['code'] ?? '')) === $countyCode) {
                return $county;
            }
        }

        return null;
    }

    public static function count(): int
    {
        return array_sum(array_map('count', self::all()));
    }
}
